window.SCIENCE_CH7_FALLBACK = {"chapter": "Chapter 7: Particulate Nature of Matter", "source": "NCERT Class 8 Science (Curiosity — Textbook of Science for Grade 8)", "totalQuestions": 120, "questions": [{"id": 1, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "What are the basic building blocks that make up any larger piece of a substance or material called?", "options": ["Dust specks", "Constituent particles", "Mineral grains", "Surface crystals"], "correctIndex": 1, "explanation": "A constituent particle is the basic unit that makes up a larger piece of any substance or material.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100"}, {"id": 2, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "Grinding a stick of chalk into fine powder using a mortar and pestle is an example of which type of change?", "options": ["Chemical change", "Biological change", "Irreversible chemical reaction", "Physical change"], "correctIndex": 3, "explanation": "Grinding chalk only reduces the size of each speck without forming any new substance, so it is a physical change.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 99"}, {"id": 3, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "Can the constituent particles of chalk or sugar be seen through an ordinary microscope?", "options": ["No, they are so small that they cannot be seen even through an ordinary microscope", "Only when dissolved in oil", "Yes, with an ordinary school microscope", "Yes, easily with a hand lens"], "correctIndex": 0, "explanation": "Constituent particles of matter are extremely small—far too small to be visible even under an ordinary microscope.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 4, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "Which ancient Indian philosopher first proposed the idea of 'Parmanu' (tiny, indivisible eternal particles of matter)?", "options": ["Sushruta", "Charaka", "Acharya Kanad", "Aryabhata"], "correctIndex": 2, "explanation": "Acharya Kanad first spoke about the concept of Parmanu (atom) as tiny, indivisible, eternal particles making up matter.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 5, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "In which ancient Indian treatise did Acharya Kanad write about the idea of Parmanu?", "options": ["Vaisheshika Sutras", "Arthashastra", "Aryabhatiya", "Charaka Samhita"], "correctIndex": 0, "explanation": "Acharya Kanad recorded his philosophy of Parmanu in his foundational work, the Vaisheshika Sutras.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 6, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "When sugar is stirred into water until it disappears, how can we still confirm that sugar is present in the top layer of water?", "options": ["By tasting a spoonful from the top layer—it tastes sweet", "Because the water turns bright pink", "By seeing large crystals floating on top", "Because the water freezes immediately"], "correctIndex": 0, "explanation": "Even though sugar particles are invisible after dissolving, tasting the top layer proves they have spread throughout the water.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100"}, {"id": 7, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "How many constituent particles make up a single tiny grain of sugar?", "options": ["Exactly one particle", "Millions and millions of constituent particles", "About ten particles", "A few hundred particles"], "correctIndex": 1, "explanation": "Each tiny visible grain of sugar is composed of millions and millions of extremely small constituent particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100"}, {"id": 8, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "Is a single fine grain of river sand or clay the smallest possible unit of a rock?", "options": ["No, each grain of sand or clay is itself made up of a huge number of constituent particles", "Yes, sand cannot be divided further", "Only clay is made of particles, not sand", "Only wet sand has particles"], "correctIndex": 0, "explanation": "Just like chalk powder, fine grains of sand and clay are still composed of huge numbers of constituent particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 99–100"}, {"id": 9, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "If we could somehow remove ALL the constituent particles from a wooden chair, what would happen?", "options": ["Nothing of the chair would remain", "The chair would just weigh slightly less", "The chair would turn into a liquid", "Nothing would change"], "correctIndex": 0, "explanation": "Because the entire chair is made up of its constituent particles, removing all of them leaves nothing of the chair behind.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q3)"}, {"id": 10, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "In the mountains, what natural process gradually breaks big rocks down into pebbles, stones, sand, and clay?", "options": ["Sublimation", "Evaporation", "Erosion by flowing rivers", "Condensation"], "correctIndex": 2, "explanation": "Erosion breaks mountain rocks down, and flowing rivers further grind them into pebbles, stones, sand, and clay.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 99"}, {"id": 11, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "What happens to the constituent particles of sugar when sugar dissolves completely in water?", "options": ["They separate and occupy the available interparticle spaces between water particles", "They turn into water particles", "They evaporate immediately into air", "They are destroyed permanently"], "correctIndex": 0, "explanation": "Dissolved sugar breaks into its constituent particles, which spread out and fit into the interparticle spaces between water particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100–101"}, {"id": 12, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "What are the attractive forces that hold the constituent particles of matter together called?", "options": ["Atmospheric pressure", "Gravitational pulls", "Magnetic repulsion", "Interparticle attractions"], "correctIndex": 3, "explanation": "Constituent particles are held together by attractive forces known as interparticle attractions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 13, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "Which two factors determine the strength of interparticle attractions in a substance?", "options": ["Colour of the substance and shape of the container", "Mass of the container and altitude only", "Nature of the substance and the interparticle distance", "Age of the substance and sunlight exposure"], "correctIndex": 2, "explanation": "The strength of interparticle attractions depends on the nature of the substance and the distance between its particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 14, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "What happens to interparticle forces of attraction when the distance between particles increases even slightly?", "options": ["They decrease drastically", "They remain completely unchanged", "They turn into electrical sparks", "They increase slightly"], "correctIndex": 0, "explanation": "The textbook explicitly notes that even a slight increase in interparticle distance decreases the interparticle forces drastically.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 15, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "Why does an inflated balloon weigh more than an empty deflated balloon even though air is invisible?", "options": ["Because air is matter composed of tiny particles that have mass and occupy space", "Because rubber expands when heated", "Because invisible light gets trapped inside", "Because balloons absorb water from air"], "correctIndex": 0, "explanation": "Air is matter made of tiny constituent particles that have mass, adding measurable weight to an inflated balloon.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 98"}, {"id": 16, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "Before stirring sugar placed at the bottom of a glass of water (Activity 7.2), why does the top layer NOT immediately taste sweet?", "options": ["Because water destroys sugar before stirring", "Because sugar particles have not yet separated and spread up to the top layer", "Because sugar floats at the top", "Because cold water cannot hold sugar"], "correctIndex": 1, "explanation": "Without stirring, the sugar remains settled at the bottom and takes time for its particles to spread to the top layer.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100"}, {"id": 17, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "Which statement best summarises the particulate nature of matter?", "options": ["All matter (solids, liquids, and gases) is composed of extremely small particles in motion", "Particles exist only when matter is heated", "Only solids are made of particles; liquids and gases are continuous", "Matter contains no empty space at all"], "correctIndex": 0, "explanation": "All three states of matter are composed of extremely small constituent particles separated by interparticle spaces.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101 & 113"}, {"id": 18, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Medium", "question": "What ultimately decides whether a substance exists as a solid, a liquid, or a gas?", "options": ["The size of the beaker it is kept in", "The strength of interparticle forces of attraction (governed by thermal energy and spacing)", "The number of times it is stirred", "The colour of its particles"], "correctIndex": 1, "explanation": "The strength of interparticle attractions—determined by particle spacing and thermal energy—decides the physical state of matter.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101 & 112"}, {"id": 19, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "CHS Exam", "question": "According to Acharya Kanad, what were the three key characteristics of 'Parmanu'?", "options": ["Liquid, colourful, and weightless", "Magnetic, heavy, and fragile", "Large, visible, and temporary", "Tiny, indivisible, and eternal"], "correctIndex": 3, "explanation": "Acharya Kanad described Parmanu as tiny, indivisible, and eternal particles making up all matter.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 20, "topic": "Composition of Matter & Acharya Kanad", "difficulty": "Easy", "question": "Why does ocean water taste salty even though no salt crystals are visible in it?", "options": ["Sunlight makes pure water salty", "Salt turns into liquid fish oil", "Ocean water contains tiny white sand grains", "Dissolved salt breaks into invisible constituent particles that occupy spaces between water particles"], "correctIndex": 3, "explanation": "Just like sugar in water, dissolved salt separates into tiny invisible constituent particles distributed throughout ocean water.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q9)"}, {"id": 21, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "Why do solids like an iron nail, stone, or wooden block have a definite shape and definite volume?", "options": ["They contain trapped air bubbles", "Their particles are tightly packed and held in fixed positions by very strong interparticle attractions", "They have no interparticle attractions", "Their particles move freely in all directions"], "correctIndex": 1, "explanation": "Very strong interparticle attractions hold solid particles tightly in fixed positions, giving solids a fixed shape and volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102"}, {"id": 22, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "How do constituent particles move in the solid state?", "options": ["They fly freely across the container", "They never have any motion at all", "They only vibrate (oscillate) to and fro about their fixed positions", "They slide smoothly past one another"], "correctIndex": 2, "explanation": "Solid particles cannot move past each other; they only vibrate or oscillate to and fro about their fixed positions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102"}, {"id": 23, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "What happens to the constituent particles of a solid when it is heated?", "options": ["They stop vibrating completely", "They shrink in size", "They stick together even more tightly", "They vibrate more vigorously until they leave their fixed positions"], "correctIndex": 3, "explanation": "Heating gives particles more thermal energy, making them vibrate vigorously until interparticle forces weaken and the solid melts.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102"}, {"id": 24, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "What is the 'melting point' of a solid?", "options": ["The maximum temperature a solid can reach before burning", "The room temperature of a laboratory", "The temperature at which a liquid turns into gas", "The minimum temperature at which a solid melts to become a liquid at atmospheric pressure"], "correctIndex": 3, "explanation": "Melting point is defined as the minimum temperature at which a solid converts into a liquid at atmospheric pressure.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103"}, {"id": 25, "topic": "Solid State & Melting Point", "difficulty": "CHS Exam", "question": "According to Table 7.1 of NCERT Class 8 Curiosity, what is the melting point of Urea?", "options": ["133 °C", "0 °C", "1538 °C", "100 °C"], "correctIndex": 0, "explanation": "Table 7.1 lists the melting points of Ice (0 °C), Urea (133 °C), and Iron (1538 °C).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103 (Table 7.1)"}, {"id": 26, "topic": "Solid State & Melting Point", "difficulty": "CHS Exam", "question": "According to Table 7.1, what is the melting point of Iron?", "options": ["1000 °C", "133 °C", "538 °C", "1538 °C"], "correctIndex": 3, "explanation": "Iron has very strong interparticle forces of attraction, giving it a high melting point of 1538 °C.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103 (Table 7.1)"}, {"id": 27, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "What is the melting point of Ice at atmospheric pressure (Table 7.1)?", "options": ["0 °C", "4 °C", "100 °C", "-10 °C"], "correctIndex": 0, "explanation": "Ice melts to form liquid water at 0 °C under normal atmospheric pressure.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103 (Table 7.1)"}, {"id": 28, "topic": "Solid State & Melting Point", "difficulty": "CHS Exam", "question": "Generally, particles in a liquid are farther apart than in a solid. Which common substance is explicitly noted as an EXCEPTION to this rule?", "options": ["Urea", "Aluminium", "Iron", "Ice (its particles are farther apart than those in liquid water)"], "correctIndex": 3, "explanation": "Ice is a notable exception—its particles are actually farther apart in solid ice than in liquid water.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103"}, {"id": 29, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "Why does Iron (1538 °C) have a much higher melting point than Ice (0 °C) and Urea (133 °C)?", "options": ["Iron has much stronger interparticle forces of attraction requiring more heat energy to overcome", "Iron particles are larger than urea grains", "Iron does not contain constituent particles", "Iron has weaker interparticle forces"], "correctIndex": 0, "explanation": "Solids with stronger interparticle attractive forces have higher melting points because more thermal energy is needed to weaken them.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103"}, {"id": 30, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "During the melting process of a solid, what happens to the interparticle forces of attraction?", "options": ["They decrease (weaken) so particles can leave fixed positions", "They remain completely unchanged", "They become stronger", "They vanish completely like in gases"], "correctIndex": 0, "explanation": "At the melting point, thermal energy weakens interparticle attractions enough for particles to leave their fixed positions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102 & 113"}, {"id": 31, "topic": "Solid State & Melting Point", "difficulty": "CHS Exam", "question": "Grains of rice or rice flour take the shape of the jar they are poured into. Are they solids or liquids?", "options": ["Solids, because each individual grain retains its own definite shape and volume", "Gases, because air sits between grains", "Liquids, because they take the container's shape", "Fluids, just like water"], "correctIndex": 0, "explanation": "Each individual rice or flour grain is a solid with a fixed shape and volume; only the collection of many small grains conforms to the jar.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q10)"}, {"id": 32, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "Why is it possible to pile up stones or sand in a heap, but not a liquid like water?", "options": ["Stones and sand grains are solids with fixed shapes that do not flow away, whereas water particles slide past each other", "Water is heavier than stone", "Sand has no interparticle attractions", "Water evaporates instantly on touching air"], "correctIndex": 0, "explanation": "Solids retain fixed shapes and stay piled up, whereas liquid particles slide freely past one another causing water to flow.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 98"}, {"id": 33, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "In Activity 7.3, hammering an iron nail, rock salt, stone, wooden block, key, and aluminium shows that:", "options": ["All solids break into identical powder easily", "Solids have strong interparticle forces, though the strength varies depending on the nature of the material", "Wood has stronger forces than iron", "None of them are made of particles"], "correctIndex": 1, "explanation": "All six objects are solids with strong interparticle attractions, yet iron and aluminium resist breaking far more strongly than rock salt.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102"}, {"id": 34, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "Compared to liquids and gases, the interparticle spacing in solids is:", "options": ["Zero with no space at all", "Maximum", "Equal to gases", "Minimum"], "correctIndex": 3, "explanation": "Solids have the minimum interparticle spacing among the three states of matter.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112–113"}, {"id": 35, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "In the solid state, the thermal (heat) energy of constituent particles is:", "options": ["Low, restricting their motion to small vibrations in fixed positions", "Infinite", "Very high", "Equal to gases"], "correctIndex": 0, "explanation": "Low thermal energy in solids keeps particles close together under strong attraction, allowing only small vibrations.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 36, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "Why can you NOT move your finger through a solid wooden block the way you can through water?", "options": ["Water is made of gases", "In solids, interparticle attractions are very strong and hold particles rigidly in fixed positions", "Wood has no particles", "Wood has a low melting point"], "correctIndex": 1, "explanation": "Strong interparticle forces prevent solid particles from being temporarily displaced by a finger.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 37, "topic": "Solid State & Melting Point", "difficulty": "CHS Exam", "question": "Arrange Ice, Urea, and Iron in INCREASING order of their interparticle forces of attraction based on Table 7.1:", "options": ["Ice < Urea < Iron", "Urea < Ice < Iron", "Iron < Urea < Ice", "Ice < Iron < Urea"], "correctIndex": 0, "explanation": "Higher melting point indicates stronger interparticle attraction: Ice (0 °C) < Urea (133 °C) < Iron (1538 °C).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103 (Table 7.1)"}, {"id": 38, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "What happens to the energy supplied to a solid at its melting point?", "options": ["It destroys the constituent particles", "It turns the solid directly into iron", "It is lost without any change of state", "It is used to overcome interparticle attractive forces so the solid converts into a liquid"], "correctIndex": 3, "explanation": "At the melting point, thermal energy overcomes interparticle attractive forces, allowing particles to move out of fixed positions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 39, "topic": "Solid State & Melting Point", "difficulty": "Easy", "question": "Which of the following is an example of a solid whose particles are closely packed in fixed positions?", "options": ["Aluminium foil", "Methane gas", "Glycerin", "Steam"], "correctIndex": 0, "explanation": "Aluminium foil is a solid (Exercise Q7), glycerin is a liquid, and methane gas is a gas.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q7)"}, {"id": 40, "topic": "Solid State & Melting Point", "difficulty": "Medium", "question": "Why do two solid blocks placed side by side NOT mix easily on their own the way two gases do?", "options": ["Solids repel each other magnetically", "Solid particles are locked in fixed positions by strong attractions and cannot move freely past each other", "Solid particles move faster than gas particles", "Solids have no mass"], "correctIndex": 1, "explanation": "Unlike gases whose particles move freely across large spaces, solid particles only vibrate in fixed positions and cannot intermingle easily.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q4)"}, {"id": 41, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "What are the shape and volume characteristics of a liquid?", "options": ["Fixed shape, but no fixed volume", "Neither fixed shape nor fixed volume", "No fixed shape, but a definite (fixed) volume", "Fixed shape and fixed volume"], "correctIndex": 2, "explanation": "Liquids take the shape of their container (no fixed shape) while maintaining a fixed volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 104"}, {"id": 42, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "In Activity 7.4, pouring 200 mL of water successively from Container A to differently shaped Containers B and C proves that:", "options": ["Liquids have no fixed shape but have a definite volume", "Water compresses to half its volume", "Liquids are solids at room temperature", "Water changes its volume with container shape"], "correctIndex": 0, "explanation": "The water changes shape to match each container while staying at the 200 mL mark, proving liquids have fixed volume but no fixed shape.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 104"}, {"id": 43, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "In Activity 7.4, why might the water level appear slightly less than 200 mL after pouring into the next container if the container is not clean?", "options": ["Water particles disappear permanently", "Water turns into solid ice", "Some water sticks to the walls of the previous container", "Gravity reduces the volume of water"], "correctIndex": 2, "explanation": "The textbook notes that if a container is not clean, a small amount of water may cling to its walls during transfer.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 104"}, {"id": 44, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "How do particles move in the liquid state?", "options": ["They fly out to fill the entire room instantly", "They are completely frozen in place", "They vibrate only without changing neighbours", "They move freely, but only within a limited space (sliding past each other)"], "correctIndex": 3, "explanation": "Liquid particles can move past each other freely, yet interparticle attractions keep them within a limited volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 104 & 112"}, {"id": 45, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "When you move your finger through water in a shallow vessel and remove it, what happens and why?", "options": ["Water is temporarily displaced and immediately restores its position because liquid attractions are slightly weaker than in solids", "The water freezes around the finger", "The water turns into vapour", "A permanent cut remains in the water"], "correctIndex": 0, "explanation": "Interparticle attractions in liquids are slightly weaker than in solids, letting particles shift aside temporarily and then rejoin.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 46, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "What is the 'boiling point' of a liquid?", "options": ["The temperature at which a solid freezes", "The temperature at which a liquid boils and turns into vapour at atmospheric pressure", "The temperature at which evaporation stops", "Any temperature above 0 °C"], "correctIndex": 1, "explanation": "Boiling point is the temperature at which a liquid boils rapidly and turns into vapour at atmospheric pressure.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 47, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "CHS Exam", "question": "How does vapour formation at the BOILING POINT differ from EVAPORATION?", "options": ["Boiling is fast and occurs both at the surface and within the liquid (bubbles); evaporation is slow, occurs only at the surface, and happens at all temperatures", "There is no difference between boiling and evaporation", "Boiling occurs slowly only at the surface; evaporation forms bubbles throughout", "Evaporation occurs only at 100 °C"], "correctIndex": 0, "explanation": "At boiling point, vapour forms rapidly throughout the bulk liquid (seen as bubbles), whereas evaporation happens slowly only at the surface at any temperature.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 48, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "Why does spilled water on a floor disappear after some time even without heating it to 100 °C?", "options": ["Because of boiling", "Because of evaporation, which occurs slowly at the surface at all temperatures", "Because water turns into a solid", "Because floor tiles destroy water particles"], "correctIndex": 1, "explanation": "Spilled water disappears through evaporation—surface particles gradually escape into the air even below the boiling point.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 49, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "What visible sign shows that vapour is forming within the bulk of a liquid at its boiling point?", "options": ["Change in colour of the vessel", "Bubble formation throughout the liquid", "Formation of frost on the outside", "Decrease in vessel temperature"], "correctIndex": 1, "explanation": "At the boiling point, rapid vapour formation inside the liquid appears as bubbles rising to the surface.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 50, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "What is the primary difference between solids and liquids (Exercise Q1)?", "options": ["Liquids have stronger attractions than solids", "Particles are closely packed in solids, while stationary in liquids", "Particles are far apart in solids and fixed in liquids", "Particles are closely packed in solids and move past each other in liquids"], "correctIndex": 3, "explanation": "In solids particles are closely packed in fixed positions, whereas in liquids they can move past each other.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 113 (Exercise Q1)"}, {"id": 51, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "When milk in a glass tumbler is spilled on a table, milk flows and spreads out while the glass tumbler keeps its shape. Why?", "options": ["Glass has weaker interparticle attractions than milk", "Milk is a liquid whose particles slide past each other, while glass is a solid with tightly fixed particles", "Glass is lighter than milk", "Milk is a gas at room temperature"], "correctIndex": 1, "explanation": "Milk is a fluid (liquid) with weaker attractions allowing particles to flow, while the glass tumbler is a rigid solid.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q5)"}, {"id": 52, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "Why does water take the shape of folded hands when held, but lose that shape as soon as you release it?", "options": ["Because water particles cannot move", "Because hands melt the water", "Because water has no fixed shape and its particles are free to move and flow", "Because water has no volume"], "correctIndex": 2, "explanation": "Water is a liquid—it takes the shape of whatever holds it and flows away once released.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 98 & 104"}, {"id": 53, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "How does the interparticle attraction in liquids compare to solids and gases?", "options": ["Stronger than solids and weaker than gases", "Slightly weaker than in solids, but much stronger than in gases", "Zero", "Equal to gases"], "correctIndex": 1, "explanation": "Interparticle attraction is strongest in solids, slightly weaker in liquids, and minimum (negligible) in gases.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112–113"}, {"id": 54, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "When a liquid is heated to its boiling point, what happens to its constituent particles?", "options": ["They pack closer together", "They turn into solid crystals", "Their movement becomes so vigorous that interparticle attractions weaken and particles escape as vapour", "They slow down and freeze"], "correctIndex": 2, "explanation": "Vigorous motion at the boiling point overcomes interparticle attractions, allowing particles to escape into the gaseous state.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 55, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "Which of the following substances from Exercise Q7 is a LIQUID at room temperature?", "options": ["Aluminium foil", "Rock salt", "Glycerin", "Methane"], "correctIndex": 2, "explanation": "Glycerin is a liquid whose particles are slightly loosely packed and move within a limited space.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q7)"}, {"id": 56, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "Compared to solids, how is the interparticle spacing in liquids described in NCERT Curiosity?", "options": ["Ten times smaller than in solids", "Zero spacing", "A little more than in solids (except water vs. ice)", "Identical to gases"], "correctIndex": 2, "explanation": "Liquid particles are a little loosely packed with slightly more interparticle spacing than solids (with ice being the exception).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 103 & 112"}, {"id": 57, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "CHS Exam", "question": "Assertion (A): Liquids have a definite volume even though they have no fixed shape. Reason (R): Liquid particles can move past each other, yet interparticle attractions remain strong enough to keep them within a limited space.", "options": ["A is true, but R is false", "Both A and R are true, but R is NOT the correct explanation of A", "Both A and R are true, and R is the correct explanation of A", "A is false, but R is true"], "correctIndex": 2, "explanation": "Liquid particles slide freely (no fixed shape), while moderate attractions keep them close together (fixed volume).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 104–105"}, {"id": 58, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "Which state of matter is formed immediately when solid wax melts near the wick of a burning candle?", "options": ["Chalk powder", "Molten liquid wax", "Gaseous wax directly", "Solid ice"], "correctIndex": 1, "explanation": "A burning candle shows solid wax, molten liquid wax near the wick, and wax vapour around the flame.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q8)"}, {"id": 59, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Easy", "question": "Evaporation occurs at:", "options": ["All temperatures, slowly and at the surface", "Only 0 °C", "Only 100 °C", "Only inside closed syringes"], "correctIndex": 0, "explanation": "Evaporation takes place at all temperatures below the boiling point, slowly and only from the surface of the liquid.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105"}, {"id": 60, "topic": "Liquid State, Boiling & Evaporation", "difficulty": "Medium", "question": "Why are liquids practically incompressible when pushed inside a sealed syringe?", "options": ["Because liquid particles do not move", "Because syringes cannot hold water", "Because liquid particles have very little free space between them compared to gases", "Because water turns to iron under pressure"], "correctIndex": 2, "explanation": "Unlike gases, liquid particles are already quite close together, so external pressure barely reduces their volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107"}, {"id": 61, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "Which statement correctly describes the shape and volume of gases?", "options": ["Fixed shape and fixed volume", "Fixed shape, no fixed volume", "Neither a fixed shape nor a fixed volume", "No fixed shape, fixed volume"], "correctIndex": 2, "explanation": "Gases acquire the shape of their container and expand to occupy the entire available space, having neither fixed shape nor fixed volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106"}, {"id": 62, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "In Activity 7.5, when the glass plate separating Gas Jar A (filled with incense smoke) and Gas Jar B (empty) is removed, what happens?", "options": ["The smoke stays strictly inside Gas Jar A", "Both jars shatter", "The smoke turns into liquid water", "The smoke spreads freely to fill the entire space of Gas Jar B as well"], "correctIndex": 3, "explanation": "Smoke spreads into Gas Jar B and fills all available space, showing gases have no fixed volume and move freely in all directions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 105–106"}, {"id": 63, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "CHS Exam", "question": "In Activity 7.5, why does smoke help us observe the motion of invisible gas particles?", "options": ["Because smoke is heavier than iron", "Because tiny smoke particles suspended in air are constantly hit by invisible gas particles", "Because smoke is a pure liquid", "Because smoke stops air from moving"], "correctIndex": 1, "explanation": "Tiny visible smoke particles suspended in air are continuously struck by invisible moving gas particles, revealing gas motion.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106"}, {"id": 64, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "CHS Exam", "question": "Which purple/violet vapour is mentioned in NCERT Curiosity as an alternative to incense smoke for demonstrating gas spreading in a closed jar?", "options": ["Mercury vapour", "Carbon dioxide snow", "Iodine vapour (obtained from solid iodine)", "Chlorine vapour"], "correctIndex": 2, "explanation": "Placing solid iodine in a closed gas jar produces visible iodine vapour that spreads freely inside the jar (with caution as it can cause irritation).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106 (Fig. 7.8)"}, {"id": 65, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "Why are BOTH liquids and gases classified together as 'fluids'?", "options": ["Because both are easily compressible", "Because both are invisible", "Because both have fixed volume", "Because both can flow and do not retain a fixed shape"], "correctIndex": 3, "explanation": "Both liquids and gases can flow and lack a fixed shape, which distinguishes them from solids and classifies them as fluids.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106"}, {"id": 66, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "How strong are the interparticle attractions in the gaseous state?", "options": ["Maximum (strongest)", "Minimum / negligible", "Moderate", "Equal to iron"], "correctIndex": 1, "explanation": "In gases, particles are very far apart and interparticle attractions are minimum (negligible).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106 & 112"}, {"id": 67, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "In Activity 7.6 (syringe without a needle), pushing the plunger inwards while blocking the open end with your thumb shows that:", "options": ["Air turns into solid sand", "Air volume decreases because gas particles have large spaces between them that can be reduced by pressure", "The syringe melts", "Air cannot be compressed"], "correctIndex": 1, "explanation": "Compressing air forces gas particles closer together, proving gases have large interparticle spaces.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107"}, {"id": 68, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "In Activity 7.6, what happens when you stop pushing the compressed syringe plunger?", "options": ["The plunger stays stuck forever", "Water forms inside the syringe", "The syringe collapses inward", "The gas particles spread out again, pushing the plunger back to its original position"], "correctIndex": 3, "explanation": "When external pressure is removed, the constantly moving gas particles spread back out and push the plunger to its original position.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107"}, {"id": 69, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "What do you observe when you repeat Activity 7.6 by filling the syringe with WATER instead of air?", "options": ["Water compresses even more easily than air", "Water disappears", "Water freezes when pushed", "Water is practically incompressible"], "correctIndex": 3, "explanation": "Repeating the syringe test with water shows that liquids are practically incompressible compared to gases.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107"}, {"id": 70, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "Which safety precaution is specifically given in NCERT Curiosity when demonstrating Activity 7.5 with solid iodine?", "options": ["Mix iodine with sugar", "Heat it with bare hands", "Be careful because vapours of iodine can cause irritation", "Inhale the vapour deeply"], "correctIndex": 2, "explanation": "The Safety First box warns that vapours of iodine can cause irritation, so solid iodine must be handled carefully.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106"}, {"id": 71, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "In which state of matter is the interparticle spacing MAXIMUM?", "options": ["Solid", "Gas", "Liquid", "All three have equal spacing"], "correctIndex": 1, "explanation": "Gases have the maximum interparticle spacing and the highest freedom of particle movement.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 72, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "Why do gases mix with each other very easily, whereas solids do not?", "options": ["Gas particles have large interparticle spaces, negligible attraction, and move freely in all directions", "Solids have no thermal energy at all", "Gases have stronger attractions than solids", "Gas particles are heavier than solid particles"], "correctIndex": 0, "explanation": "Free random motion and huge interparticle spaces let gas particles intermingle rapidly.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q4)"}, {"id": 73, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "Which substance from Exercise Q7 is a GAS whose particles are far apart and free to move?", "options": ["Aluminium foil", "Urea", "Methane", "Glycerin"], "correctIndex": 2, "explanation": "Methane is a gas at room temperature, with maximum interparticle spacing and negligible attraction.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q7)"}, {"id": 74, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "Why can a large volume of cooking gas (LPG) or oxygen be stored inside a relatively small cylinder?", "options": ["Because gases have large interparticle spaces and can be compressed by applying external pressure", "Because cylinders destroy half the gas", "Because gas particles shrink to zero mass", "Because gases are solids inside metal"], "correctIndex": 0, "explanation": "High compressibility due to huge interparticle spaces allows large amounts of gas to be packed into cylinders under pressure.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107"}, {"id": 75, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "CHS Exam", "question": "Arrange Solid, Liquid, and Gas in DECREASING order of compressibility:", "options": ["Gas > Solid > Liquid", "Gas > Liquid > Solid", "Liquid > Gas > Solid", "Solid > Liquid > Gas"], "correctIndex": 1, "explanation": "Gases are highly compressible, liquids are practically incompressible, and solids are rigid and virtually incompressible.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 107 & 112"}, {"id": 76, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "How do gas particles behave inside a closed container?", "options": ["They stick only to the lid", "They vibrate in fixed rows", "They move freely and rapidly in all directions, filling the entire container", "They settle at the bottom like sand"], "correctIndex": 2, "explanation": "Gas particles have enough thermal energy to overcome attractions and move freely in every direction.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106 & 112"}, {"id": 77, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "Which of the following is NOT a fluid?", "options": ["Rock salt", "Air", "Water", "Glycerin"], "correctIndex": 0, "explanation": "Rock salt is a solid with a fixed shape; liquids (water, glycerin) and gases (air) are fluids.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 102 & 106"}, {"id": 78, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "CHS Exam", "question": "If you transfer 100 mL of a gas from a small bottle into a 1-litre empty flask, what will be the volume of the gas inside the flask?", "options": ["100 mL only", "1 litre (it expands to occupy the entire available space)", "500 mL", "Zero"], "correctIndex": 1, "explanation": "Gases have no fixed volume—they always expand to fill the entire available volume of their container.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 106"}, {"id": 79, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Medium", "question": "In the gaseous state, why do particles have complete freedom of movement?", "options": ["Because gas particles are solid spheres glued together", "Because gravity does not act on gases", "Because gases have zero mass", "Because their thermal energy is high enough to overcome interparticle attractive forces"], "correctIndex": 3, "explanation": "High thermal energy enables gas particles to overcome attractive forces and move freely in all directions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 80, "topic": "Gaseous State, Fluids & Compressibility", "difficulty": "Easy", "question": "When a candle is extinguished just after burning, the white wispy smoke rising from the wick is mainly:", "options": ["Wax vapour (gaseous state of wax) mixing with air", "Solid rock salt", "Iron filings", "Liquid water droplets"], "correctIndex": 0, "explanation": "A freshly extinguished candle displays solid wax, molten liquid wax, and rising wax vapour (gaseous state).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q8)"}, {"id": 81, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "What are the tiny empty gaps between constituent particles of matter called?", "options": ["Air pockets", "Interparticle spaces", "Liquid channels", "Dust pores"], "correctIndex": 1, "explanation": "The spaces present between constituent particles of matter are known as interparticle spaces.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101"}, {"id": 82, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "What fills the tiny interparticle spaces between the closely packed constituent particles of a solid?", "options": ["Air", "Water vapour", "Nothing at all (completely empty space)", "Microscopic dust"], "correctIndex": 2, "explanation": "NCERT Curiosity explicitly warns against the misconception that air fills interparticle spaces—they contain nothing at all!", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 83, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "In Activity 7.7, water is marked at level A, sugar is added raising it to B, and after stirring to dissolve the sugar, level C is marked. What is observed?", "options": ["Water disappears", "Level C rises much higher than B", "The glass overflows completely", "Level C decreases slightly compared to B, showing the solution's volume is less than the sum of water + sugar volumes"], "correctIndex": 3, "explanation": "Initially adding sugar raises the level (A→B), but upon dissolving, sugar particles occupy interparticle spaces in water so level C drops slightly below B.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108"}, {"id": 84, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "What happens to the total water level in a glass vessel when insoluble SAND is added and stirred?", "options": ["The level drops back to A", "The water evaporates instantly", "Sand settles at the bottom and occupies space, causing the total level/volume to increase", "Sand dissolves completely into interparticle spaces"], "correctIndex": 2, "explanation": "Because sand does not dissolve in water, its grains settle at the bottom and displace water, increasing the total volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 85, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "Sugar and sand are both solids. Why does sugar dissolve in water while sand does NOT?", "options": ["Water particles stop moving around sand", "Sugar is actually a liquid", "Sand is not made of particles", "In sand, constituent particles are held together so strongly that moving water particles cannot pull them out"], "correctIndex": 3, "explanation": "Constituent particles of insoluble substances like sand are bound too strongly for water particles to pull them apart.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110"}, {"id": 86, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "Which of the following are examples of SOLUBLE solids mentioned in Activity 7.7?", "options": ["Wood chips and pebbles", "Sugar, common salt, and glucose", "Chalk and iron filings", "Sand and stone pieces"], "correctIndex": 1, "explanation": "Activity 7.7 lists sugar, common salt, and glucose as soluble solids, and sand and stone pieces as insoluble solids.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108"}, {"id": 87, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "In air pollution studies (mentioned in 'A Step Further'), what does SPM stand for?", "options": ["Solid Pressure Measurement", "Standard Particle Mass", "Suspended Particulate Matter", "Surface Pollution Meter"], "correctIndex": 2, "explanation": "SPM stands for Suspended Particulate Matter—tiny dust particles suspended in the air.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 88, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "Are the tiny dust particles of Suspended Particulate Matter (SPM) the same as the constituent particles (atoms/molecules) of matter?", "options": ["Yes, SPM particles cannot be seen even with electron microscopes", "No, SPM is a liquid", "No, even a tiny SPM dust particle is made up of a very large number of constituent particles (atoms and molecules)", "Yes, one dust speck is a single atom"], "correctIndex": 2, "explanation": "SPM refers to tiny dust specks suspended in air—each speck is still made up of a huge number of far smaller atoms and molecules.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 89, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "Arrange Solid, Liquid, and Gas in INCREASING order of interparticle spacing:", "options": ["Solid < Liquid < Gas", "Solid < Gas < Liquid", "Liquid < Solid < Gas", "Gas < Liquid < Solid"], "correctIndex": 0, "explanation": "Interparticle spacing is minimum in solids, slightly more in liquids, and maximum in gases.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109 & 112"}, {"id": 90, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "Do closely packed solids still have any interparticle space at all between their particles?", "options": ["Only in wooden solids", "Yes, despite close packing, some tiny empty space remains between the particles", "Only when melted", "No, zero space exists"], "correctIndex": 1, "explanation": "Fig. 7.12a shows that even in closely packed solids, small empty interparticle spaces exist between particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 91, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "When common salt dissolves in water, why is the final volume of the salt solution less than the sum of the separate volumes of salt and water?", "options": ["Salt evaporates during stirring", "Salt particles fit into the interparticle spaces between water particles", "Water shrinks permanently", "Salt turns into air"], "correctIndex": 1, "explanation": "Dissolved salt particles occupy existing interparticle spaces among water particles, keeping the total volume smaller than the arithmetic sum.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108"}, {"id": 92, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "Which of the following solids will settle at the bottom and increase the water level without dissolving?", "options": ["Potassium permanganate", "Glucose", "Stone pieces", "Common salt"], "correctIndex": 2, "explanation": "Stone pieces are insoluble in water, so they settle at the bottom and raise the total volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108–109"}, {"id": 93, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "What does the word 'constituent' mean in 'constituent particles of matter'?", "options": ["A chemical impurity", "Something visible only under sunlight", "Being a basic, essential part that makes up a whole substance", "Something added from outside"], "correctIndex": 2, "explanation": "Constituent particles (atoms and molecules) are the fundamental building blocks that make up any material.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 100 & 109"}, {"id": 94, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "In Fig. 7.11, the magnified schematic of sugar dissolved in water shows:", "options": ["No water particles left", "Tiny sugar particles evenly distributed in the spaces between water particles", "All sugar particles clumped at the bottom", "Sugar particles floating only on the surface"], "correctIndex": 1, "explanation": "Fig. 7.11 illustrates dissolved sugar particles nestled in the interparticle spaces throughout the water.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108 (Fig. 7.11)"}, {"id": 95, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "If you add two spoons of glucose to water and stir well, the water level after dissolving will:", "options": ["Double in height", "Overflow immediately", "Turn into solid ice", "Drop slightly compared to the level right after adding undissolved glucose"], "correctIndex": 3, "explanation": "Like sugar and salt, glucose is soluble—its particles enter the interparticle spaces of water, slightly lowering the level after dissolution.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108"}, {"id": 96, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "Which statement is FALSE according to Chapter 7?", "options": ["Sugar particles occupy interparticle spaces in water", "Interparticle spaces in solids are filled with air", "Interparticle spaces are smallest in solids", "Gases have the largest interparticle spaces"], "correctIndex": 1, "explanation": "Interparticle spaces contain NOTHING at all—they are NOT filled with air!", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 97, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "What are the ultra-tiny constituent particles that make up even a single dust speck of SPM?", "options": ["Pebbles and sand", "Air bubbles", "Drops of water", "Atoms and molecules"], "correctIndex": 3, "explanation": "Even a tiny dust particle is composed of a very large number of constituent particles—atoms and molecules.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 98, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Medium", "question": "Why does increasing the distance between particles change a solid into a liquid or gas?", "options": ["Because gravity reverses", "Because particles lose all their mass", "Because air enters between the particles", "Because interparticle attractive forces weaken drastically as distance increases"], "correctIndex": 3, "explanation": "Greater spacing drastically weakens interparticle attractions, allowing particles to move more freely.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 101 & 112"}, {"id": 99, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "Easy", "question": "In Activity 7.7, which tool is used to stir the sugar in the glass vessel?", "options": ["Plastic syringe", "Iron hammer", "Glass rod", "Mortar and pestle"], "correctIndex": 2, "explanation": "A glass rod is used to stir and dissolve the sugar in Activity 7.7 (Fig. 7.10c).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 108"}, {"id": 100, "topic": "Interparticle Spaces, Solubility & SPM", "difficulty": "CHS Exam", "question": "Assertion (A): Adding sand to water increases the total volume in the beaker. Reason (R): Sand is insoluble in water, so its particles cannot break apart to occupy water's interparticle spaces.", "options": ["Both A and R are true, but R is NOT the correct explanation of A", "A is false, but R is true", "A is true, but R is false", "Both A and R are true, and R is the correct explanation of A"], "correctIndex": 3, "explanation": "Sand particles stay strongly bound together, settle at the bottom, and occupy extra space, raising the total volume.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109–110"}, {"id": 101, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "In Activity 7.8, when a few grains of potassium permanganate are dropped into still water, what colour spreads throughout the water?", "options": ["Uniform pink / purple-pink", "Deep yellow", "Bright green", "Milky white"], "correctIndex": 0, "explanation": "Initially streaks of pink colour spread out from the grain until the entire water turns a uniform pink colour.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110 (Fig. 7.13)"}, {"id": 102, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "Why does potassium permanganate spread throughout still water even without stirring (Activity 7.8)?", "options": ["Because glass attracts pink colour", "Because water particles are in constant motion—they pull out potassium permanganate particles and hit them until they spread evenly", "Because potassium permanganate has tiny motors", "Because air pushes the water downward"], "correctIndex": 1, "explanation": "Constantly moving water particles pull out potassium permanganate particles from the grain and collide with them, spreading them evenly.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110"}, {"id": 103, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "What safety precaution must be followed when handling potassium permanganate in Activity 7.8?", "options": ["Boil it with petrol", "Crush it with bare fingers", "Taste a small grain first", "Do not touch it with bare hands; use a spoon or spatula"], "correctIndex": 3, "explanation": "The Safety First box instructs not to touch potassium permanganate with bare hands and to use a spoon or spatula.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 109"}, {"id": 104, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "In the 'Think Like a Scientist' experiment comparing hot water, room-temperature water, and ice-cold water, where does potassium permanganate spread the FASTEST?", "options": ["Room-temperature water", "Same speed in all three", "Ice-cold water", "Hot water"], "correctIndex": 3, "explanation": "Water particles move fastest in hot water and slowest in ice-cold water, so spreading is fastest in hot water.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110"}, {"id": 105, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "What conclusion is drawn from potassium permanganate spreading fastest in hot water and slowest in ice-cold water?", "options": ["Heat stops particle motion", "Temperature has no effect on particles", "Cold water has more energy than hot water", "The movement of particles increases when heat (thermal energy) is provided"], "correctIndex": 3, "explanation": "Providing heat increases the thermal energy and speed of movement of constituent particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110"}, {"id": 106, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "In Activity 7.9, when an incense stick is lit in one corner of a room, why does its fragrance soon reach every corner?", "options": ["Because walls absorb and re-emit smell", "Because incense smoke is a solid", "Because air particles are constantly moving, hitting the fragrance particles and helping them spread across the room", "Because gravity pulls smell sideways"], "correctIndex": 2, "explanation": "Constantly moving air particles collide with fragrance particles and carry them throughout the room.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110–111"}, {"id": 107, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "CHS Exam", "question": "How do soap particles clean oil stains from clothes ('Ever Heard Of...', Fig. 7.15)?", "options": ["Numerous soap particles surround the oil—one end attaches to oil and the other mixes with water, lifting and washing the oil away", "Soap melts the fabric", "Soap turns oil into solid sand", "Soap only bleaches the colour of oil"], "correctIndex": 0, "explanation": "Each soap particle has one end that attaches to oil and another end that mixes with water, surrounding oil particles and washing them off.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 111 (Fig. 7.15)"}, {"id": 108, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "CHS Exam", "question": "Evaluate Statement (vi) from Exercise Q2: 'On heating camphor, we are adding energy to the camphor, and the energy is released as a smell.' Is this TRUE or FALSE?", "options": ["False — camphor cannot be heated", "True — smell has no particles", "True — energy itself turns into smell", "False — heating gives camphor particles thermal energy so they escape as vapour particles that spread through air to reach our nose"], "correctIndex": 3, "explanation": "Smell is not energy being released; heating adds thermal energy so camphor particles break free as vapour and diffuse through the air.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q2-vi)"}, {"id": 109, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "When camphor is heated in one corner of a room, its fragrance reaches all corners because:", "options": ["Camphor turns into liquid water", "Solid camphor jumps across the room", "Camphor vapour particles move freely and spread throughout the air", "Air freezes around camphor"], "correctIndex": 2, "explanation": "Heating turns camphor into vapour whose particles move freely and diffuse across the entire room.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 114 (Exercise Q2-v)"}, {"id": 110, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "According to Page 112 of NCERT Curiosity, what single factor ultimately governs interparticle distance, attraction strength, and thus the physical state of matter?", "options": ["Sound waves", "Thermal (heat) energy of the particles", "Colour of the substance", "Shape of the container"], "correctIndex": 1, "explanation": "Thermal energy governs particle motion and interparticle distance, which in turn determines attraction strength and physical state.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 111, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "Why does the aroma of hot sizzling food reach you from several metres away much faster than cold food?", "options": ["Hot air blocks smell", "Cold food is heavier than iron", "Particles from hot food have higher thermal energy and move faster through the air", "Cold food has no particles"], "correctIndex": 2, "explanation": "Higher temperature increases particle kinetic/thermal energy, making aroma particles spread much faster.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110–111"}, {"id": 112, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "In which state of matter is particle movement described as 'negligible (only vibrations)'?", "options": ["Plasma", "Solid", "Gas", "Liquid"], "correctIndex": 1, "explanation": "The summary chart on Page 112 states that particle movement in solids is negligible (only vibrations).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 113, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "In which state of matter is particle movement 'restricted to a limited space'?", "options": ["Gas", "Liquid", "Solid", "Vacuum"], "correctIndex": 1, "explanation": "In liquids, particles move past each other freely but remain restricted to a limited volume/space.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 114, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Easy", "question": "In which state of matter can particles move freely in 'all the available space'?", "options": ["Crystal", "Solid", "Liquid", "Gas"], "correctIndex": 3, "explanation": "Gas particles have negligible attraction and move freely in all available space.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}, {"id": 115, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "Why does perfume sprayed on one side of a classroom quickly reach students sitting on the other side?", "options": ["Perfume turns into solid crystals", "Light carries perfume particles", "Perfume droplets roll along the floor", "Perfume vapour particles mix and collide with constantly moving air particles"], "correctIndex": 3, "explanation": "Just like incense fragrance, perfume particles spread through the room via collisions with constantly moving air particles.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 111"}, {"id": 116, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "CHS Exam", "question": "If you drop a crystal of potassium permanganate into ice-cold water (2 °C) and another into hot water (70 °C), which statement is correct?", "options": ["Both turn uniformly pink at the exact same second", "Potassium permanganate is insoluble in hot water", "The 2 °C tumbler turns pink faster", "The 70 °C tumbler turns uniformly pink much faster because water particles move faster at higher temperatures"], "correctIndex": 3, "explanation": "Higher thermal energy in 70 °C water makes water particles move much faster, speeding up the spreading of potassium permanganate.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 110"}, {"id": 117, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "When ice melts into water and then boils into water vapour, what happens to the thermal energy and spacing of particles?", "options": ["Thermal energy decreases and spacing decreases", "Particles merge into one giant particle", "Thermal energy increases, overcoming interparticle attractions so particles move much farther apart as vapour", "Thermal energy stays zero"], "correctIndex": 2, "explanation": "Heating raises thermal energy from solid → liquid → gas, overcoming attractions and greatly increasing spacing in vapour.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112 & 114"}, {"id": 118, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "CHS Exam", "question": "Which of the following correctly pairs a state of matter with its particle properties?", "options": ["Liquid → Maximum spacing, no volume", "Solid → Minimum attraction, maximum spacing", "Gas → Negligible attraction, maximum spacing, free motion in all directions", "Solid → Free motion in all directions"], "correctIndex": 2, "explanation": "Gases are defined by negligible interparticle attraction, maximum spacing, and free motion in all directions.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112–113"}, {"id": 119, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "Medium", "question": "Why does water alone struggle to wash away an oil stain from cloth without soap?", "options": ["Water particles cannot attach to oil; soap particles bridge the two by attaching one end to oil and the other to water", "Oil is heavier than iron", "Water is a solid on fabric", "Oil dissolves instantly in plain water"], "correctIndex": 0, "explanation": "Soap particles have dual ends—one attaches to oil and the other mixes with water—allowing oil stains to lift off and rinse away.", "ncertRef": "NCERT Curiosity Ch. 7 • Page 111"}, {"id": 120, "topic": "Particle Motion, Thermal Energy & Applications", "difficulty": "CHS Exam", "question": "Arrange Solid, Liquid, and Gas in INCREASING order of particle kinetic/thermal energy for the same substance (e.g., ice, water, steam):", "options": ["Gas < Liquid < Solid", "Liquid < Solid < Gas", "Solid < Liquid < Gas", "Solid < Gas < Liquid"], "correctIndex": 2, "explanation": "Thermal energy is lowest in solids (small vibrations), higher in liquids (sliding motion), and highest in gases (free rapid motion).", "ncertRef": "NCERT Curiosity Ch. 7 • Page 112"}]};
